use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use uuid::Uuid;
#[derive(Serialize,Deserialize,Debug)] pub struct Envelope { pub version:u8, #[serde(rename="messageId")] pub message_id:String, #[serde(rename="type")] pub r#type:String, #[serde(rename="deviceId",skip_serializing_if="Option::is_none")] pub device_id:Option<String>, #[serde(rename="taskId",skip_serializing_if="Option::is_none")] pub task_id:Option<String>, pub payload:Value }
#[derive(Serialize)] pub struct RootRequest { pub label:String }
#[derive(Serialize)] pub struct PairPayload { pub code:String, pub name:String, #[serde(rename="publicKey")] pub public_key:String, pub version:String, pub roots:Vec<RootRequest> }
impl Envelope { fn make(kind:&str,device:Option<&str>,task:Option<&str>,payload:Value)->Self { Self{version:1,message_id:Uuid::new_v4().to_string(),r#type:kind.into(),device_id:device.map(str::to_owned),task_id:task.map(str::to_owned),payload} } pub fn pair(payload:PairPayload)->Self {Self::make("pair",None,None,serde_json::to_value(payload).unwrap())} pub fn hello(device:&str,credential:&str,version:&str)->Self {Self::make("hello",Some(device),None,json!({"credential":credential,"version":version}))} pub fn heartbeat(device:&str,credential:&str)->Self {Self::make("heartbeat",Some(device),None,json!({"credential":credential}))} pub fn task_result(device:&str,task:&str,credential:&str,payload:Value)->Self { let status=payload.get("status").and_then(Value::as_str).unwrap_or("completed"); Self::make("task_result",Some(device),Some(task),json!({"status":status,"credential":credential,"result":payload}))} pub fn task_error(device:&str,task:&str,credential:&str,error:String)->Self {Self::make("task_error",Some(device),Some(task),json!({"status":"failed","credential":credential,"error":error}))} }
